//! What a language analyzer is and what it produces.

pub mod file_analysis;
pub mod lang;
pub mod registry;
#[cfg(feature = "lang-ts")]
pub mod ts;

pub use file_analysis::{Degradation, FileAnalysis};
pub use lang::{AnalysisProfile, AnalyzerCapabilities, CapabilityPrecision, LanguageAnalyzer, LanguageId};
//! The ordered set of analyzers that decides which one owns a path.

use std::sync::Arc;

use camino::Utf8Path;

use super::lang::LanguageAnalyzer;

/// Analyzers in registration order.
///
/// Callers ask the registry which analyzer owns a file instead of naming a concrete analyzer.
///
/// # Examples
///
/// ```
/// use monokl::analysis::registry::AnalyzerRegistry;
///
/// let registry = AnalyzerRegistry::new(Vec::new());
/// assert!(registry.analyzer_for("a.ts".into()).is_none());
/// ```
pub struct AnalyzerRegistry {
    analyzers: Vec<Arc<dyn LanguageAnalyzer>>,
}

impl AnalyzerRegistry {
    /// Builds a registry that consults `analyzers` in the given order.
    pub fn new(analyzers: Vec<Arc<dyn LanguageAnalyzer>>) -> Self {
        Self { analyzers }
    }

    /// Returns the first registered analyzer whose [`LanguageAnalyzer::supports`] accepts `path`.
    ///
    /// # Examples
    ///
    /// ```
    /// use monokl::analysis::registry::AnalyzerRegistry;
    ///
    /// assert!(AnalyzerRegistry::new(Vec::new()).analyzer_for("a.ts".into()).is_none());
    /// ```
    pub fn analyzer_for(&self, path: &Utf8Path) -> Option<&dyn LanguageAnalyzer> {
        self.analyzers.iter().find(|analyzer| analyzer.supports(path)).map(Arc::as_ref)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::analysis::file_analysis::FileAnalysis;
    use crate::analysis::lang::{AnalysisProfile, AnalyzerCapabilities, CapabilityPrecision, LanguageId};
    use crate::error::{MonoklError, Result};

    /// Claims every path ending in `extension` and reports its one language for it.
    struct ByExtension {
        extension: &'static str,
        languages: [LanguageId; 1],
    }

    impl LanguageAnalyzer for ByExtension {
        fn languages(&self) -> &[LanguageId] {
            &self.languages
        }
        fn supports(&self, path: &Utf8Path) -> bool {
            path.extension() == Some(self.extension)
        }
        fn language_for(&self, path: &Utf8Path) -> Option<LanguageId> {
            self.supports(path).then_some(self.languages[0])
        }
        fn capabilities(&self, _language: LanguageId) -> AnalyzerCapabilities {
            AnalyzerCapabilities {
                blocks: true,
                classified_imports: false,
                resolved_import_graph: CapabilityPrecision::Unsupported,
                refs: CapabilityPrecision::Unsupported,
                definition: CapabilityPrecision::Unsupported,
                inspect_detail: CapabilityPrecision::Unsupported,
            }
        }
        fn analyze_with_profile(
            &self,
            _path: &Utf8Path,
            _source: Box<dyn FnOnce() -> Result<String>>,
            _profile: AnalysisProfile,
        ) -> Result<Arc<FileAnalysis>> {
            Err(MonoklError::TooManyTerms { count: 0, limit: 0 })
        }
    }

    fn analyzer(extension: &'static str, language: LanguageId) -> Arc<dyn LanguageAnalyzer> {
        Arc::new(ByExtension { extension, languages: [language] })
    }

    #[test]
    fn first_registered_match_owns_the_path() {
        let registry = AnalyzerRegistry::new(vec![
            analyzer("ts", LanguageId::TypeScript),
            analyzer("rs", LanguageId::Rust),
            analyzer("ts", LanguageId::Go),
        ]);
        let owner = registry.analyzer_for(Utf8Path::new("src/a.ts")).unwrap();
        assert_eq!(owner.languages(), [LanguageId::TypeScript]);
        let owner = registry.analyzer_for(Utf8Path::new("src/lib.rs")).unwrap();
        assert_eq!(owner.languages(), [LanguageId::Rust]);
    }

    #[test]
    fn unowned_path_has_no_analyzer() {
        let registry = AnalyzerRegistry::new(vec![analyzer("ts", LanguageId::TypeScript)]);
        assert!(registry.analyzer_for(Utf8Path::new("README.md")).is_none());
        assert!(AnalyzerRegistry::new(Vec::new()).analyzer_for(Utf8Path::new("a.ts")).is_none());
    }
}
//! Everything extracted from one source file.

use std::fmt;

use camino::Utf8PathBuf;

use super::lang::AnalysisProfile;
use crate::digest::Digest;
use crate::types::{CodeBlock, DependencyRecord, ExportRecord, JsxElementEntry, LangData, SymbolEntry};

/// Why a file was analyzed without its content: the analyzer gave up on it instead of reading it.
///
/// A file with syntax errors is not degraded this way; its recovered content is kept and only
/// [`FileAnalysis::had_parse_errors`] is set.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[non_exhaustive]
pub enum Degradation {
    /// The source is longer than the analyzer will parse.
    TooLarge {
        /// The length of the source.
        bytes: usize,
        /// The longest source the analyzer parses.
        cap: usize,
    },
    /// The parse or extraction panicked.
    Panicked,
    /// The analyzer could not start the thread the parse runs on.
    ThreadUnavailable,
}

impl fmt::Display for Degradation {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::TooLarge { bytes, cap } => {
                write!(f, "file too large to parse ({bytes} bytes, over the cap of {cap})")
            }
            Self::Panicked => f.write_str("parser panicked"),
            Self::ThreadUnavailable => f.write_str("could not start a parse thread"),
        }
    }
}

/// The result of analyzing one file.
///
/// It owns all its data, so it can outlive the parse that produced it. Under [`AnalysisProfile::Dependencies`] only
/// `dependencies` is filled; under [`AnalysisProfile::Structural`] `blocks` is empty. `profile` records which, so a
/// cache never serves a partial result as a full one.
#[derive(Clone, Debug)]
pub struct FileAnalysis {
    pub source_path: Utf8PathBuf,
    pub digest: Digest,
    pub profile: AnalysisProfile,
    /// Set for any file that did not parse cleanly, including every file with a [`Degradation`].
    pub had_parse_errors: bool,
    /// Why the file's content is missing, when the analyzer gave up on it.
    pub degradation: Option<Degradation>,
    pub symbols: Vec<SymbolEntry>,
    pub dependencies: Vec<DependencyRecord>,
    pub exports: Vec<ExportRecord>,
    pub blocks: Vec<CodeBlock>,
    pub lang: LangData,
}

impl FileAnalysis {
    /// The language name.
    #[must_use]
    pub fn language(&self) -> &str {
        match &self.lang {
            LangData::Ts(_) => "typescript",
        }
    }

    /// The JSX elements of the file.
    #[must_use]
    pub fn jsx_elements(&self) -> &[JsxElementEntry] {
        self.lang.jsx_elements()
    }

    /// Whether this is a TypeScript file.
    #[must_use]
    pub fn is_typescript(&self) -> bool {
        matches!(self.lang, LangData::Ts(_))
    }
}

#[cfg(test)]
mod tests {
    use rstest::rstest;

    use super::*;
    use crate::types::TsData;

    fn analysis(lang: LangData) -> FileAnalysis {
        FileAnalysis {
            source_path: Utf8PathBuf::from("src/a.ts"),
            digest: Digest::blake3(b"x"),
            profile: AnalysisProfile::Structural,
            had_parse_errors: true,
            degradation: None,
            symbols: Vec::new(),
            dependencies: Vec::new(),
            exports: Vec::new(),
            blocks: Vec::new(),
            lang,
        }
    }

    fn jsx(name: &str) -> JsxElementEntry {
        JsxElementEntry { name: name.to_string(), is_html: false, line: 1, attributes: Vec::new() }
    }

    #[test]
    fn a_typescript_analysis_names_its_language() {
        let analysis = analysis(LangData::Ts(TsData::default()));
        assert_eq!(analysis.language(), "typescript");
        assert!(analysis.is_typescript());
        assert!(analysis.jsx_elements().is_empty());
    }

    #[rstest]
    #[case(Degradation::TooLarge { bytes: 300_000, cap: 260_096 }, "file too large to parse (300000 bytes, over the cap of 260096)")]
    #[case(Degradation::Panicked, "parser panicked")]
    #[case(Degradation::ThreadUnavailable, "could not start a parse thread")]
    fn a_degradation_names_its_reason(#[case] degradation: Degradation, #[case] text: &str) {
        assert_eq!(degradation.to_string(), text);
    }

    #[test]
    fn typescript_files_expose_their_jsx_elements_in_order() {
        let ts = TsData { jsx_elements: vec![jsx("App"), jsx("Button")], ..TsData::default() };
        let analysis = analysis(LangData::Ts(ts));
        let names: Vec<_> = analysis.jsx_elements().iter().map(|e| e.name.as_str()).collect();
        assert_eq!(names, ["App", "Button"]);
    }

    fn assert_owned<T: Clone + std::fmt::Debug + Send + Sync + 'static>(_: &T) {}

    #[test]
    fn a_file_analysis_is_owned_and_clones_faithfully() {
        let original = analysis(LangData::Ts(TsData::default()));
        assert_owned(&original);
        let clone = original.clone();
        assert_eq!(clone.source_path, original.source_path);
        assert_eq!(clone.digest, original.digest);
        assert_eq!(clone.profile, AnalysisProfile::Structural);
        assert_eq!(clone.had_parse_errors, original.had_parse_errors);
        assert_eq!(clone.degradation, original.degradation);
        assert_eq!(format!("{clone:?}"), format!("{original:?}"));
    }
}
//! The contract every language analyzer implements.

use std::sync::Arc;

use camino::Utf8Path;

use super::file_analysis::FileAnalysis;
use crate::error::Result;

/// A language monokl can name.
///
/// Variants are ordered as declared, so a `BTreeSet<LanguageId>` iterates in that order.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
#[non_exhaustive]
pub enum LanguageId {
    TypeScript,
    Rust,
    Python,
    Go,
    Java,
    C,
    Cpp,
    Bash,
    CSharp,
    Ruby,
    Php,
    Kotlin,
    Scala,
}

/// How well a capability can be answered, from weakest to strongest.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum CapabilityPrecision {
    Unsupported,
    Heuristic,
    Structural,
    Exact,
}

/// What one analyzer can do for one language.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct AnalyzerCapabilities {
    pub blocks: bool,
    pub classified_imports: bool,
    pub resolved_import_graph: CapabilityPrecision,
    pub refs: CapabilityPrecision,
    pub definition: CapabilityPrecision,
    pub inspect_detail: CapabilityPrecision,
}

/// How much of a file to extract.
///
/// `Dependencies` fills only `dependencies`. `Structural` adds `symbols` and `exports`. `Full` adds `blocks` and the
/// per-language entries.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[non_exhaustive]
pub enum AnalysisProfile {
    Dependencies,
    Structural,
    Full,
}

/// Turns source files into [`FileAnalysis`] values.
///
/// An instance may handle several languages. [`language_for`](Self::language_for) is `None` exactly when
/// [`supports`](Self::supports) is `false`, and [`capabilities`](Self::capabilities) is only asked about languages
/// the instance returned from [`languages`](Self::languages) or [`language_for`](Self::language_for).
pub trait LanguageAnalyzer: Send + Sync {
    /// Every language this analyzer handles.
    fn languages(&self) -> &[LanguageId];

    /// Whether this analyzer handles the file at `path`.
    fn supports(&self, path: &Utf8Path) -> bool;

    /// The language `path` belongs to, or `None` when [`supports`](Self::supports) is `false`.
    fn language_for(&self, path: &Utf8Path) -> Option<LanguageId>;

    /// What this analyzer can do for `language`.
    fn capabilities(&self, language: LanguageId) -> AnalyzerCapabilities;

    /// Analyzes one file, extracting what `profile` asks for. `source` is only called if the file needs reading.
    ///
    /// # Errors
    ///
    /// Returns whatever error the implementation hits, including the one `source` returns.
    fn analyze_with_profile(
        &self,
        path: &Utf8Path,
        source: Box<dyn FnOnce() -> Result<String>>,
        profile: AnalysisProfile,
    ) -> Result<Arc<FileAnalysis>>;

    /// Analyzes one file at full fidelity.
    ///
    /// # Errors
    ///
    /// As [`analyze_with_profile`](Self::analyze_with_profile).
    fn analyze(&self, path: &Utf8Path, source: Box<dyn FnOnce() -> Result<String>>) -> Result<Arc<FileAnalysis>> {
        self.analyze_with_profile(path, source, AnalysisProfile::Full)
    }
}

#[cfg(test)]
mod tests {
    use std::cell::Cell;
    use std::collections::{BTreeSet, HashMap};
    use std::rc::Rc;
    use std::sync::Mutex;

    use camino::Utf8PathBuf;

    use super::*;
    use crate::digest::Digest;
    use crate::error::MonoklError;
    use crate::types::{LangData, TsData};

    const ALL: [LanguageId; 13] = [
        LanguageId::TypeScript,
        LanguageId::Rust,
        LanguageId::Python,
        LanguageId::Go,
        LanguageId::Java,
        LanguageId::C,
        LanguageId::Cpp,
        LanguageId::Bash,
        LanguageId::CSharp,
        LanguageId::Ruby,
        LanguageId::Php,
        LanguageId::Kotlin,
        LanguageId::Scala,
    ];

    #[test]
    fn language_ids_are_ordered_as_declared() {
        assert!(ALL.windows(2).all(|pair| pair[0] < pair[1]));
        let set: BTreeSet<_> = [LanguageId::Scala, LanguageId::TypeScript, LanguageId::Rust, LanguageId::Go].into();
        assert_eq!(
            set.into_iter().collect::<Vec<_>>(),
            [LanguageId::TypeScript, LanguageId::Rust, LanguageId::Go, LanguageId::Scala]
        );
    }

    #[test]
    fn language_ids_key_a_map() {
        let map: HashMap<_, _> = ALL.iter().copied().enumerate().map(|(i, l)| (l, i)).collect();
        assert_eq!(map[&LanguageId::Go], 3);
        assert_eq!(map.len(), 13);
    }

    #[test]
    fn precision_orders_weakest_to_strongest() {
        use CapabilityPrecision::{Exact, Heuristic, Structural, Unsupported};
        assert!(Unsupported < Heuristic && Heuristic < Structural && Structural < Exact);
    }

    #[test]
    fn capabilities_are_equal_only_when_every_field_is() {
        use CapabilityPrecision::{Exact, Unsupported};
        let base = AnalyzerCapabilities {
            blocks: true,
            classified_imports: true,
            resolved_import_graph: Exact,
            refs: Exact,
            definition: Exact,
            inspect_detail: Exact,
        };
        assert_eq!(base, base);
        let changed = [
            AnalyzerCapabilities { blocks: false, ..base },
            AnalyzerCapabilities { classified_imports: false, ..base },
            AnalyzerCapabilities { resolved_import_graph: Unsupported, ..base },
            AnalyzerCapabilities { refs: Unsupported, ..base },
            AnalyzerCapabilities { definition: Unsupported, ..base },
            AnalyzerCapabilities { inspect_detail: Unsupported, ..base },
        ];
        assert!(changed.iter().all(|c| *c != base));
    }

    fn analysis(path: &str, profile: AnalysisProfile) -> FileAnalysis {
        FileAnalysis {
            source_path: Utf8PathBuf::from(path),
            digest: Digest::blake3(b"x"),
            profile,
            had_parse_errors: false,
            degradation: None,
            symbols: Vec::new(),
            dependencies: Vec::new(),
            exports: Vec::new(),
            blocks: Vec::new(),
            lang: LangData::Ts(TsData::default()),
        }
    }

    /// Records what `analyze_with_profile` receives and returns a canned result for `ok.ts`.
    struct Recorder {
        seen: Mutex<Vec<(Utf8PathBuf, AnalysisProfile)>>,
        ok: Arc<FileAnalysis>,
    }

    impl LanguageAnalyzer for Recorder {
        fn languages(&self) -> &[LanguageId] {
            &[LanguageId::TypeScript]
        }
        fn supports(&self, _path: &Utf8Path) -> bool {
            true
        }
        fn language_for(&self, _path: &Utf8Path) -> Option<LanguageId> {
            Some(LanguageId::TypeScript)
        }
        fn capabilities(&self, _language: LanguageId) -> AnalyzerCapabilities {
            AnalyzerCapabilities {
                blocks: true,
                classified_imports: true,
                resolved_import_graph: CapabilityPrecision::Exact,
                refs: CapabilityPrecision::Structural,
                definition: CapabilityPrecision::Structural,
                inspect_detail: CapabilityPrecision::Structural,
            }
        }
        fn analyze_with_profile(
            &self,
            path: &Utf8Path,
            _source: Box<dyn FnOnce() -> Result<String>>,
            profile: AnalysisProfile,
        ) -> Result<Arc<FileAnalysis>> {
            self.seen.lock().unwrap().push((path.to_owned(), profile));
            if path.file_name() == Some("ok.ts") {
                Ok(Arc::clone(&self.ok))
            } else {
                Err(MonoklError::TooManyTerms { count: 1, limit: 1 })
            }
        }
    }

    fn recorder() -> Recorder {
        Recorder { seen: Mutex::new(Vec::new()), ok: Arc::new(analysis("ok.ts", AnalysisProfile::Full)) }
    }

    #[test]
    fn analyze_runs_the_full_profile_and_passes_results_through() {
        let analyzer = recorder();
        let called = Rc::new(Cell::new(false));
        let source = || {
            let flag = Rc::clone(&called);
            Box::new(move || {
                flag.set(true);
                Ok(String::new())
            }) as Box<dyn FnOnce() -> Result<String>>
        };
        let got = analyzer.analyze(Utf8Path::new("a/ok.ts"), source());
        assert!(Arc::ptr_eq(&got.unwrap(), &analyzer.ok));
        let err = analyzer.analyze(Utf8Path::new("bad.ts"), source()).unwrap_err();
        assert!(matches!(err, MonoklError::TooManyTerms { count: 1, limit: 1 }), "got {err:?}");
        assert_eq!(
            *analyzer.seen.lock().unwrap(),
            [
                (Utf8PathBuf::from("a/ok.ts"), AnalysisProfile::Full),
                (Utf8PathBuf::from("bad.ts"), AnalysisProfile::Full)
            ]
        );
        assert!(!called.get(), "analyze must not call the source closure itself");
    }

    #[test]
    fn an_analyzer_is_shareable_across_threads() {
        let analyzer: Arc<dyn LanguageAnalyzer> = Arc::new(recorder());
        let languages = std::thread::spawn(move || analyzer.languages().to_vec()).join().unwrap();
        assert_eq!(languages, [LanguageId::TypeScript]);
    }
}

//! The TypeScript and JavaScript analyzer.

mod parse;

use std::sync::Arc;

use camino::Utf8Path;

use super::file_analysis::FileAnalysis;
use super::lang::{AnalysisProfile, AnalyzerCapabilities, CapabilityPrecision, LanguageAnalyzer, LanguageId};
use crate::digest::Digest;
use crate::error::Result;
use crate::types::{LangData, TsData};

const LANGUAGES: [LanguageId; 1] = [LanguageId::TypeScript];

/// Analyzes TypeScript and JavaScript files with OXC.
///
/// It is stateless: every call parses its own source and returns owned data. Dependencies keep their specifier as
/// written; resolving them to files is not done here.
///
/// # Examples
///
/// ```
/// use camino::Utf8Path;
/// use monokl::analysis::LanguageAnalyzer;
/// use monokl::analysis::ts::TsAnalyzer;
///
/// let analyzer = TsAnalyzer::new();
/// assert!(analyzer.supports(Utf8Path::new("src/app.tsx")));
/// assert!(!analyzer.supports(Utf8Path::new("types/global.d.ts")));
/// ```
#[derive(Clone, Copy, Debug, Default)]
pub struct TsAnalyzer;

impl TsAnalyzer {
    /// Creates an analyzer.
    ///
    /// # Examples
    ///
    /// ```
    /// use monokl::analysis::ts::TsAnalyzer;
    ///
    /// let _analyzer = TsAnalyzer::new();
    /// ```
    #[must_use]
    pub const fn new() -> Self {
        Self
    }
}

impl LanguageAnalyzer for TsAnalyzer {
    fn languages(&self) -> &[LanguageId] {
        &LANGUAGES
    }

    fn supports(&self, path: &Utf8Path) -> bool {
        !(path.as_str().ends_with(".d.ts") || path.as_str().ends_with(".d.mts") || path.as_str().ends_with(".d.cts"))
            && matches!(path.extension(), Some("ts" | "tsx" | "js" | "jsx" | "mts" | "cts" | "mjs" | "cjs"))
    }

    fn language_for(&self, path: &Utf8Path) -> Option<LanguageId> {
        self.supports(path).then_some(LanguageId::TypeScript)
    }

    fn capabilities(&self, _language: LanguageId) -> AnalyzerCapabilities {
        AnalyzerCapabilities {
            blocks: true,
            classified_imports: false,
            resolved_import_graph: CapabilityPrecision::Unsupported,
            refs: CapabilityPrecision::Structural,
            definition: CapabilityPrecision::Structural,
            inspect_detail: CapabilityPrecision::Structural,
        }
    }

    fn analyze_with_profile(
        &self,
        path: &Utf8Path,
        source: Box<dyn FnOnce() -> Result<String>>,
        profile: AnalysisProfile,
    ) -> Result<Arc<FileAnalysis>> {
        let source = source()?;
        let digest = Digest::blake3(source.as_bytes());
        let parse::Extraction {
            symbols,
            dependencies,
            exports,
            blocks,
            jsx_elements,
            type_only_imports,
            had_parse_errors,
            degradation,
        } = parse::extract(path, &source, profile);
        Ok(Arc::new(FileAnalysis {
            source_path: path.to_owned(),
            digest,
            profile,
            had_parse_errors,
            degradation,
            symbols,
            dependencies,
            exports,
            blocks,
            lang: LangData::Ts(TsData { jsx_elements, type_only_imports, unresolved_aliases: Vec::new() }),
        }))
    }
}

#[cfg(test)]
mod tests {
    use std::cell::Cell;
    use std::rc::Rc;

    use rstest::rstest;

    use super::*;
    use crate::analysis::Degradation;
    use crate::error::MonoklError;
    use crate::types::{BindingKind, DependencyTarget, SymbolKind};

    const FIXTURES: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/small-ts");

    fn analyze_source(path: &str, text: &str, profile: AnalysisProfile) -> Arc<FileAnalysis> {
        let text = text.to_owned();
        TsAnalyzer::new().analyze_with_profile(Utf8Path::new(path), Box::new(move || Ok(text)), profile).unwrap()
    }

    fn fixture(relative: &str) -> String {
        std::fs::read_to_string(format!("{FIXTURES}/{relative}")).unwrap()
    }

    fn analyze_fixture(relative: &str, profile: AnalysisProfile) -> Arc<FileAnalysis> {
        analyze_source(&format!("src/{relative}"), &fixture(&format!("src/{relative}")), profile)
    }

    type Symbol<'a> = (&'a str, SymbolKind, usize, Option<&'a str>);
    type Binding<'a> = (&'a str, &'a str, BindingKind);

    fn symbols(analysis: &FileAnalysis) -> Vec<Symbol<'_>> {
        analysis.symbols.iter().map(|s| (s.name.as_str(), s.kind, s.line, s.signature.as_deref())).collect()
    }

    fn exports(analysis: &FileAnalysis) -> Vec<(&str, usize, bool)> {
        analysis.exports.iter().map(|e| (e.name.as_str(), e.line, e.re_export)).collect()
    }

    fn dependencies(analysis: &FileAnalysis) -> Vec<(&str, usize, Vec<Binding<'_>>)> {
        analysis
            .dependencies
            .iter()
            .map(|dep| {
                let DependencyTarget::File { specifier, resolved, is_relative } = &dep.target;
                assert_eq!(*resolved, None);
                assert_eq!(*is_relative, specifier.starts_with('.'));
                let bindings = dep.bindings.iter().map(|b| (b.imported.as_str(), b.local.as_str(), b.kind)).collect();
                (specifier.as_str(), dep.line, bindings)
            })
            .collect()
    }

    fn blocks(analysis: &FileAnalysis) -> Vec<(usize, usize, SymbolKind, Option<&str>)> {
        analysis
            .blocks
            .iter()
            .map(|b| {
                assert_eq!(b.file, analysis.source_path);
                (b.line_start, b.line_end, b.node_kind, b.symbol_signature.as_deref())
            })
            .collect()
    }

    #[rstest]
    #[case("a.ts", true)]
    #[case("a.tsx", true)]
    #[case("a.js", true)]
    #[case("a.jsx", true)]
    #[case("a.mts", true)]
    #[case("a.cts", true)]
    #[case("a.mjs", true)]
    #[case("a.cjs", true)]
    #[case("src/deep/dir/a.ts", true)]
    #[case("types.d.ts", false)]
    #[case("types.d.mts", false)]
    #[case("types.d.cts", false)]
    #[case("src/types/global.d.ts", false)]
    #[case("a.rs", false)]
    #[case("a.json", false)]
