//! Monokl's core data types: symbols, dependencies, per-language data and search results.
use camino::Utf8PathBuf;

/// The classification of a symbol.
///
/// Most variants apply to every language analyzer; `Impl` and `Macro` are Rust-specific, and `Other` is the catch-all.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum SymbolKind {
    Function,
    Method,
    Constructor,
    Class,
    Struct,
    Enum,
    Interface,
    TypeAlias,
    Property,
    Field,
    Variable,
    Module,
    Impl,
    Macro,
    Other,
}

/// The visibility of a symbol.
///
/// There is no `Super` variant: Rust's `pub(super)` and `pub(in ...)` map to [`Visibility::Module`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum Visibility {
    Public,
    Crate,
    Module,
    Private,
}

/// A symbol found in a source file.
#[derive(Debug, Clone)]
pub struct SymbolEntry {
    pub name: String,
    pub kind: SymbolKind,
    pub line: usize,
    pub signature: Option<String>,
    /// The type that owns this symbol, such as the target of the enclosing `impl` block.
    pub owner: Option<String>,
    pub trait_impl: Option<String>,
    pub visibility: Option<Visibility>,
    pub kind_detail: Option<String>,
}

/// The kind of a single import binding within a [`DependencyBinding`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum BindingKind {
    Named,
    Default,
    Namespace,
    Glob,
}

/// The resolved target of a dependency statement.
///
#[derive(Debug, Clone)]
#[non_exhaustive]
pub enum DependencyTarget {
    File { specifier: String, resolved: Option<Utf8PathBuf>, is_relative: bool },
}

/// A single binding introduced by a [`DependencyRecord`].
#[derive(Debug, Clone)]
pub struct DependencyBinding {
    pub imported: String,
    pub local: String,
    pub kind: BindingKind,
}

/// A single dependency statement in a source file.
#[derive(Debug, Clone)]
pub struct DependencyRecord {
    pub line: usize,
    pub bindings: Vec<DependencyBinding>,
    pub target: DependencyTarget,
}

/// A single named export statement.
#[derive(Debug, Clone)]
pub struct ExportRecord {
    pub name: String,
    pub line: usize,
    pub re_export: bool,
}

/// A single JSX attribute.
#[derive(Debug, Clone)]
pub struct JsxAttribute {
    pub name: String,
    pub string_value: Option<String>,
    pub is_expression: bool,
    pub is_spread: bool,
}

/// A single JSX element usage.
#[derive(Debug, Clone)]
pub struct JsxElementEntry {
    pub name: String,
    pub is_html: bool,
    pub line: usize,
    pub attributes: Vec<JsxAttribute>,
}

/// TypeScript-specific analysis output.
#[derive(Debug, Clone, Default)]
pub struct TsData {
    pub jsx_elements: Vec<JsxElementEntry>,
    pub type_only_imports: Vec<String>,
    pub unresolved_aliases: Vec<String>,
}

/// Per-language analysis output.
#[derive(Debug, Clone)]
#[non_exhaustive]
pub enum LangData {
    Ts(TsData),
}

impl LangData {
    /// Returns the TypeScript data.
    pub fn ts(&self) -> &TsData {
        match self {
            LangData::Ts(ts) => ts,
        }
    }

    /// Returns the JSX elements of the TypeScript data.
    pub fn jsx_elements(&self) -> &[JsxElementEntry] {
        &self.ts().jsx_elements
    }
}

/// A block of code matched by the search pipeline.
#[derive(Debug, Clone)]
pub struct CodeBlock {
    pub file: Utf8PathBuf,
    pub line_start: usize,
    pub line_end: usize,
    pub node_kind: SymbolKind,
    pub code: String,
    pub symbol_signature: Option<String>,
    pub matched_lines: Vec<usize>,
    pub matched_keywords: Vec<String>,
    /// The block this one is a member of, such as the class of a method; `None` for a top-level block.
    pub parent: Option<ParentContext>,
}

/// The symbol enclosing a [`CodeBlock`], such as the class or object literal a method block belongs to.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParentContext {
    pub kind: SymbolKind,
    pub name: String,
    pub line: usize,
}

/// A [`CodeBlock`] with its ranking scores.
#[derive(Debug, Clone)]
pub struct RankedBlock {
    pub block: CodeBlock,
    pub bm25_score: f64,
    pub coverage_boost: f64,
    pub node_type_boost: f64,
    pub final_score: f64,
    pub rank: usize,
    pub parent_context: Option<ParentContext>,
}

/// The kind of a [`Diagnostic`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum DiagnosticKind {
    Degraded,
    Skipped,
    Warning,
    /// The file held bytes that are not UTF-8, so it was searched and extracted with each invalid sequence replaced by
    /// U+FFFD.
    LossyRead,
}

/// A non-fatal problem reported alongside a command's results.
#[derive(Debug, Clone)]
pub struct Diagnostic {
    pub kind: DiagnosticKind,
    pub path: Option<Utf8PathBuf>,
    pub message: String,
}

/// A single line matched by the text searcher.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LineHit {
    pub line_number: usize,
    pub text: String,
}

/// The language filter for the search command.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[cfg_attr(feature = "cli", derive(clap::ValueEnum))]
#[non_exhaustive]
pub enum Language {
    #[cfg_attr(feature = "cli", value(name = "typescript"))]
    TypeScript,
    #[cfg_attr(feature = "cli", value(name = "javascript"))]
    JavaScript,
    #[cfg_attr(feature = "cli", value(name = "rust"))]
    Rust,
    #[cfg_attr(feature = "cli", value(name = "python"))]
    Python,
}

/// The search command's response.
#[derive(Debug, Clone)]
pub struct SearchResponse {
    pub results: Vec<RankedBlock>,
    pub total_blocks_before_truncation: usize,
    pub truncated: bool,
    pub total_bytes: usize,
    pub total_tokens: usize,
    pub diagnostics: Vec<Diagnostic>,
}

//! Pure extraction for one TypeScript or JavaScript file.
//!
//! The parse owns its arena. Everything leaving this module is owned data, so no arena-borrowed node escapes.

use std::thread;

use camino::Utf8Path;
use oxc_allocator::Allocator;
use oxc_ast::ast::{
    BindingPattern, Class, ClassElement, Declaration, ExportAllDeclaration, ExportDeclaration,
    ExportDefaultDeclaration, ExportDefaultDeclarationKind, ExportFromDeclaration, ExportNamedDeclaration, Expression,
    Function, ImportDeclaration, ImportDeclarationSpecifier, JSXAttributeItem, JSXAttributeName, JSXAttributeValue,
    JSXElement, JSXElementName, JSXMemberExpression, JSXMemberExpressionObject, MethodDefinition, MethodDefinitionKind,
    ModuleExportName, ObjectExpression, ObjectProperty, ObjectPropertyKind, Program, PropertyDefinition, PropertyKind,
    Statement, VariableDeclaration,
};
use oxc_ast_visit::{Visit, walk};
use oxc_parser::{ParseOptions, Parser};
use oxc_span::{GetSpan, SourceType, Span};

use crate::analysis::{AnalysisProfile, Degradation};
use crate::types::{
    BindingKind, CodeBlock, DependencyBinding, DependencyRecord, DependencyTarget, ExportRecord, JsxAttribute,
    JsxElementEntry, ParentContext, SymbolEntry, SymbolKind,
};

/// The fewest lines a class or object member needs to get a block of its own. A shorter one is a stub or accessor that
/// the block holding it already shows whole.
const MIN_MEMBER_LINES: usize = 3;

/// Stack reserved per byte of source. A stack overflow aborts the process, so the stack must be big enough before the
/// parse starts. Each level of the parser's or the extractor's recursion consumes at least one byte, and the costliest
/// level measured, a `[` in a type, uses 1.7 KB of stack optimized and 4.6 KB unoptimized: this is over twice that.
///
/// `debug_assertions` stands in for "unoptimized", which `cfg!` cannot ask for directly. A release profile with debug
/// assertions pays the larger budget and the smaller length cap for nothing; a profile that disables optimizations
/// without them gets the smaller budget and could overflow. Change the constant if the workspace adds such a profile.
const STACK_PER_SOURCE_BYTE: usize = if cfg!(debug_assertions) { 12 << 10 } else { 4 << 10 };

/// Stack for what does not grow with the source.
const BASE_STACK: usize = 8 << 20;

/// The most stack one parse reserves. Only touched pages are committed, but a hostile file of the longest parsed length
/// can touch about half of it (460 MiB measured), so this also bounds a parse's memory.
const MAX_STACK: usize = 1 << 30;

/// The longest source that is parsed; a longer one could need more than [`MAX_STACK`].
pub(super) const MAX_PARSED_SOURCE_LEN: usize = (MAX_STACK - BASE_STACK) / STACK_PER_SOURCE_BYTE;

/// Everything extracted from one file, before it is wrapped in a `FileAnalysis`.
#[derive(Debug, Default)]
pub(super) struct Extraction {
    pub(super) symbols: Vec<SymbolEntry>,
    pub(super) dependencies: Vec<DependencyRecord>,
    pub(super) exports: Vec<ExportRecord>,
    pub(super) blocks: Vec<CodeBlock>,
    pub(super) jsx_elements: Vec<JsxElementEntry>,
    pub(super) type_only_imports: Vec<String>,
    pub(super) had_parse_errors: bool,
    pub(super) degradation: Option<Degradation>,
}

impl Extraction {
    /// The result for a file that could not be analyzed: no data, flagged as having errors and the reason.
    fn degraded(degradation: Degradation) -> Self {
        Self { had_parse_errors: true, degradation: Some(degradation), ..Self::default() }
    }
}

/// Extracts what `profile` asks for from `source`.
///
/// A file too long to be sure of its stack, or one whose parse or extraction panics, yields [`Extraction::degraded`]
/// with the reason.
pub(super) fn extract(path: &Utf8Path, source: &str, profile: AnalysisProfile) -> Extraction {
    if source.len() > MAX_PARSED_SOURCE_LEN {
        return Extraction::degraded(Degradation::TooLarge { bytes: source.len(), cap: MAX_PARSED_SOURCE_LEN });
    }
    let stack_size = BASE_STACK + source.len() * STACK_PER_SOURCE_BYTE;
    guarded(stack_size, || parse_and_extract(path, source, profile))
}

/// Runs `run` on its own thread with `stack_size` bytes of stack. A panic, or a thread that cannot be started, yields
/// [`Extraction::degraded`] with the reason.
fn guarded(stack_size: usize, run: impl FnOnce() -> Extraction + Send) -> Extraction {
    thread::scope(|scope| {
        let builder = thread::Builder::new().name("monokl-parse".to_owned()).stack_size(stack_size);
        let Ok(handle) = builder.spawn_scoped(scope, run) else {
            return Extraction::degraded(Degradation::ThreadUnavailable);
        };
        // The closure's output is discarded on a panic, so no torn state is observable afterwards.
        handle.join().unwrap_or_else(|_| Extraction::degraded(Degradation::Panicked))
    })
}

/// JavaScript files may hold JSX whatever their extension; TypeScript files only in `.tsx`, since `<T>x` is a cast
/// elsewhere.
fn source_type_for(path: &Utf8Path) -> SourceType {
    let source_type = SourceType::from_path(path.as_std_path()).unwrap_or_else(|_| SourceType::ts());
    if source_type.is_javascript() { source_type.with_jsx(true) } else { source_type }
}

fn parse_and_extract(path: &Utf8Path, source: &str, profile: AnalysisProfile) -> Extraction {
    let allocator = Allocator::default();
    // Parentheses carry no meaning here and a `ParenthesizedExpression` node would only add a level to every walk.
    let options = ParseOptions { preserve_parens: false, ..ParseOptions::default() };
    let parsed = Parser::new(&allocator, source, source_type_for(path)).with_options(options).parse();
    // The recovered program is still used below, so record the diagnostics rather than discarding the parse.
    let had_parse_errors = parsed.fatal_error || !parsed.diagnostics.is_empty();

    let mut extractor = Extractor { path, source, profile, lines: LineIndex::new(source), out: Extraction::default() };
    for statement in &parsed.program.body {
        extractor.statement(statement);
    }
    if profile == AnalysisProfile::Full {
        extractor.jsx(&parsed.program);
    }
    Extraction { had_parse_errors, ..extractor.out }
}

/// Maps byte offsets to 1-based line numbers.
struct LineIndex {
    newlines: Vec<usize>,
}

impl LineIndex {
    fn new(source: &str) -> Self {
        Self { newlines: source.bytes().enumerate().filter(|&(_, byte)| byte == b'\n').map(|(i, _)| i).collect() }
    }

    fn line(&self, offset: u32) -> usize {
        self.newlines.partition_point(|&newline| newline < offset as usize) + 1
    }
}

struct Extractor<'s> {
    path: &'s Utf8Path,
    source: &'s str,
    profile: AnalysisProfile,
    lines: LineIndex,
    out: Extraction,
}

impl Extractor<'_> {
    fn structural(&self) -> bool {
        self.profile != AnalysisProfile::Dependencies
    }

    fn text(&self, span: Span) -> &str {
        self.source.get(span.start as usize..span.end as usize).unwrap_or_default()
    }

    fn statement(&mut self, statement: &Statement<'_>) {
        match statement {
            Statement::ImportDeclaration(decl) => self.import(decl),
            Statement::ExportDeclaration(decl) => self.export_declaration(decl),
            Statement::ExportNamedDeclaration(decl) => self.export_named(decl),
            Statement::ExportFromDeclaration(decl) => self.export_from(decl),
            Statement::ExportDefaultDeclaration(decl) => self.export_default(decl),
            Statement::ExportAllDeclaration(decl) => self.export_all(decl),
            Statement::FunctionDeclaration(function) => {
                self.function(function);
            }
            Statement::ClassDeclaration(class) => {
                self.class(class);
            }
            Statement::TSInterfaceDeclaration(decl) => {
                self.symbol(decl.id.name.as_str(), SymbolKind::Interface, decl.span, None);
            }
            Statement::TSTypeAliasDeclaration(decl) => {
                self.symbol(decl.id.name.as_str(), SymbolKind::TypeAlias, decl.span, None);
            }
            Statement::TSEnumDeclaration(decl) => {
                self.symbol(decl.id.name.as_str(), SymbolKind::Enum, decl.span, None);
            }
            Statement::VariableDeclaration(decl) => {
                self.variables(decl);
            }
            _ => {}
        }
        if self.profile == AnalysisProfile::Full {
            self.block(statement);
            self.member_blocks(statement);
        }
    }

    fn symbol(&mut self, name: &str, kind: SymbolKind, span: Span, signature: Option<String>) {
        if !self.structural() {
            return;
        }
        self.out.symbols.push(SymbolEntry {
            name: name.to_owned(),
            kind,
            line: self.lines.line(span.start),
            signature,
            owner: None,
            trait_impl: None,
            visibility: None,
            kind_detail: None,
        });
    }

    fn export(&mut self, name: String, span: Span, re_export: bool) {
        if !self.structural() {
            return;
        }
        self.out.exports.push(ExportRecord { name, line: self.lines.line(span.start), re_export });
    }

    /// Records a function symbol and returns its name; anonymous functions have none.
    fn function(&mut self, function: &Function<'_>) -> Option<String> {
        let name = function.id.as_ref()?.name.as_str();
        let signature = self.function_signature(function);
        self.symbol(name, SymbolKind::Function, function.span, Some(signature));
        Some(name.to_owned())
    }

    /// The function's text up to its body, on one line: `function f(a: A): B`.
    fn function_signature(&self, function: &Function<'_>) -> String {
        let end = function.body.as_ref().map_or(function.span.end, |body| body.span.start);
        self.signature_text(Span::new(function.span.start, end))
    }

    /// The text of `span` on one line, without a trailing `;`.
    fn signature_text(&self, span: Span) -> String {
        self.text(span).split_whitespace().collect::<Vec<_>>().join(" ").trim_end_matches(';').trim_end().to_owned()
    }

    fn class(&mut self, class: &Class<'_>) -> Option<String> {
        let name = class.id.as_ref()?.name.as_str();
        self.symbol(name, SymbolKind::Class, class.span, None);
        Some(name.to_owned())
    }

    fn variables(&mut self, decl: &VariableDeclaration<'_>) -> Vec<String> {
        let mut names = Vec::new();
        for declarator in &decl.declarations {
            if let BindingPattern::BindingIdentifier(id) = &declarator.id {
                self.symbol(id.name.as_str(), SymbolKind::Variable, declarator.span, None);
                names.push(id.name.as_str().to_owned());
            }
        }
        names
    }

    /// Records the symbols a declaration introduces and returns their names.
    fn declaration(&mut self, decl: &Declaration<'_>) -> Vec<String> {
        match decl {
            Declaration::FunctionDeclaration(function) => self.function(function).into_iter().collect(),
            Declaration::ClassDeclaration(class) => self.class(class).into_iter().collect(),
            Declaration::TSInterfaceDeclaration(decl) => {
                self.symbol(decl.id.name.as_str(), SymbolKind::Interface, decl.span, None);
                vec![decl.id.name.as_str().to_owned()]
            }
            Declaration::TSTypeAliasDeclaration(decl) => {
                self.symbol(decl.id.name.as_str(), SymbolKind::TypeAlias, decl.span, None);
                vec![decl.id.name.as_str().to_owned()]
            }
            Declaration::TSEnumDeclaration(decl) => {
                self.symbol(decl.id.name.as_str(), SymbolKind::Enum, decl.span, None);
                vec![decl.id.name.as_str().to_owned()]
            }
            Declaration::VariableDeclaration(decl) => self.variables(decl),
            Declaration::TSExternalModuleDeclaration(_)
            | Declaration::TSNamespaceDeclaration(_)
            | Declaration::TSGlobalDeclaration(_)
            | Declaration::TSImportEqualsDeclaration(_) => Vec::new(),
        }
    }

    fn import(&mut self, decl: &ImportDeclaration<'_>) {
        let specifier = decl.source.value.as_str().to_owned();
        if decl.import_kind.is_type() {
            self.out.type_only_imports.push(specifier);
            return;
        }
        let mut bindings = Vec::new();
        for specifier in decl.specifiers.iter().flatten() {
            match specifier {
                ImportDeclarationSpecifier::ImportSpecifier(named) => {
                    if !named.import_kind.is_type() {
                        bindings.push(DependencyBinding {
                            imported: module_export_name(&named.imported),
                            local: named.local.name.as_str().to_owned(),
                            kind: BindingKind::Named,
                        });
                    }
                }
                ImportDeclarationSpecifier::ImportDefaultSpecifier(default) => bindings.push(DependencyBinding {
                    imported: "default".to_owned(),
                    local: default.local.name.as_str().to_owned(),
                    kind: BindingKind::Default,
                }),
                ImportDeclarationSpecifier::ImportNamespaceSpecifier(namespace) => bindings.push(DependencyBinding {
                    imported: "*".to_owned(),
                    local: namespace.local.name.as_str().to_owned(),
                    kind: BindingKind::Namespace,
                }),
            }
        }
        self.dependency(decl.source.value.as_str(), decl.span, bindings);
    }

    fn dependency(&mut self, specifier: &str, span: Span, bindings: Vec<DependencyBinding>) {
        self.out.dependencies.push(DependencyRecord {
            line: self.lines.line(span.start),
            bindings,
            target: DependencyTarget::File {
                specifier: specifier.to_owned(),
                resolved: None,
                is_relative: specifier.starts_with('.'),
            },
        });
    }

    /// `export function f() {}`, `export const x = 1`.
    fn export_declaration(&mut self, decl: &ExportDeclaration<'_>) {
        for name in self.declaration(&decl.declaration) {
            self.export(name, decl.span, false);
        }
    }

    /// `export { a, b as c }`.
    fn export_named(&mut self, decl: &ExportNamedDeclaration<'_>) {
        for specifier in &decl.specifiers {
            self.export(module_export_name(&specifier.exported), decl.span, false);
        }
    }

    /// `export { a } from './m'`. A type-only re-export adds no runtime dependency.
    fn export_from(&mut self, decl: &ExportFromDeclaration<'_>) {
        for specifier in &decl.specifiers {
            self.export(module_export_name(&specifier.exported), decl.span, true);
        }
        if decl.export_kind.is_type() {
            return;
        }
        let bindings = decl
            .specifiers
            .iter()
            .filter(|specifier| !specifier.export_kind.is_type())
            .map(|specifier| DependencyBinding {
                imported: module_export_name(&specifier.local),
                local: module_export_name(&specifier.exported),
                kind: BindingKind::Named,
            })
            .collect();
        self.dependency(decl.source.value.as_str(), decl.span, bindings);
    }

    fn export_default(&mut self, decl: &ExportDefaultDeclaration<'_>) {
        self.export("default".to_owned(), decl.span, false);
        match &decl.declaration {
            ExportDefaultDeclarationKind::FunctionDeclaration(function) => {
                self.function(function);
            }
            ExportDefaultDeclarationKind::ClassDeclaration(class) => {
                self.class(class);
            }
            _ => {}
        }
    }

    fn export_all(&mut self, decl: &ExportAllDeclaration<'_>) {
        let (name, kind) = match &decl.exported {
            Some(exported) => (module_export_name(exported), BindingKind::Namespace),
            None => ("*".to_owned(), BindingKind::Glob),
        };
        self.export(name.clone(), decl.span, true);
        if !decl.export_kind.is_type() {
            let binding = DependencyBinding { imported: "*".to_owned(), local: name, kind };
            self.dependency(decl.source.value.as_str(), decl.span, vec![binding]);
        }
    }

    fn block(&mut self, statement: &Statement<'_>) {
        let Some(node_kind) = statement_kind(statement) else { return };
        if matches!(statement, Statement::ImportDeclaration(_)) {
            return;
        }
        let symbol_signature = match (node_kind, statement_function(statement)) {
            (SymbolKind::Function, Some(function)) => Some(self.function_signature(function)),
            _ => None,
        };
        self.push_block(statement.span(), node_kind, symbol_signature, None);
    }

    /// Pushes a block over `span`, unless it holds nothing but whitespace.
    fn push_block(
        &mut self,
        span: Span,
        node_kind: SymbolKind,
        symbol_signature: Option<String>,
        parent: Option<ParentContext>,
    ) {
        let code = self.text(span);
        if code.trim().is_empty() {
            return;
        }
        let block = CodeBlock {
            file: self.path.to_owned(),
            line_start: self.lines.line(span.start),
            line_end: self.lines.line(span.end),
            node_kind,
            code: code.to_owned(),
            symbol_signature,
            matched_lines: Vec::new(),
            matched_keywords: Vec::new(),
            parent,
        };
        self.out.blocks.push(block);
    }

    /// Pushes a block for each long member of the named class or object literal that a top-level or exported statement
    /// holds, after the statement's own block. An anonymous class has no name to give its members as a parent, so it
    /// gets none.
    fn member_blocks(&mut self, statement: &Statement<'_>) {
        if let Some(class) = statement_class(statement) {
            self.class_member_blocks(class);
        }
        for (parent, object) in self.statement_objects(statement) {

        for (parent, object) in self.statement_objects(statement) {
            for property in &object.properties {
                match property {
                    ObjectPropertyKind::ObjectProperty(property) => self.object_property_block(property, &parent),
                    ObjectPropertyKind::SpreadProperty(_) => {}
                }
            }
        }
    }

    /// The object literals a top-level or exported statement binds to a name, each with the parent its members get: the
    /// declarator's name for `const api = { ... }`, `default` for `export default { ... }`.
    fn statement_objects<'a, 'b>(
        &self,
        statement: &'b Statement<'a>,
    ) -> Vec<(ParentContext, &'b ObjectExpression<'a>)> {
        let declaration = match statement {
            Statement::VariableDeclaration(declaration) => Some(&**declaration),
            Statement::ExportDeclaration(export) => match &export.declaration {
                Declaration::VariableDeclaration(declaration) => Some(&**declaration),
                _ => None,
            },
            _ => None,
        };
        if let Some(declaration) = declaration {
            return declaration
                .declarations
                .iter()
                .filter_map(|declarator| {
                    let BindingPattern::BindingIdentifier(id) = &declarator.id else { return None };
                    let object = object_literal(declarator.init.as_ref()?)?;
                    let parent = ParentContext {
                        kind: SymbolKind::Variable,
                        name: id.name.as_str().to_owned(),
                        line: self.lines.line(declarator.span.start),
                    };
                    Some((parent, object))
                })
                .collect();
        }
        let Statement::ExportDefaultDeclaration(export) = statement else { return Vec::new() };
        let Some(object) = export.declaration.as_expression().and_then(object_literal) else { return Vec::new() };
        let parent = ParentContext {
            kind: SymbolKind::Other,
            name: "default".to_owned(),
            line: self.lines.line(export.span.start),
        };
        vec![(parent, object)]
    }

    /// A method, constructor or function-valued property of a named class.
    fn class_member_blocks(&mut self, class: &Class<'_>) {
        let Some(id) = &class.id else { return };
        let parent = ParentContext {
            kind: SymbolKind::Class,
            name: id.name.as_str().to_owned(),
            line: self.lines.line(class.span.start),
        };
        for element in &class.body.body {
            match element {
                ClassElement::MethodDefinition(method) => self.method_block(method, &parent),
                ClassElement::PropertyDefinition(property) => self.property_block(property, &parent),
                ClassElement::StaticBlock(_)
                | ClassElement::AccessorProperty(_)
                | ClassElement::TSIndexSignature(_) => {}
            }
        }
    }

    /// A method with a body: `async f(a: A): B { ... }`. Getters and setters are methods; a signature without a body
    /// (an overload or an abstract method) is not.
    fn method_block(&mut self, method: &MethodDefinition<'_>, parent: &ParentContext) {
        let Some(body) = &method.value.body else { return };
        let node_kind = match method.kind {
            MethodDefinitionKind::Constructor => SymbolKind::Constructor,
            MethodDefinitionKind::Method | MethodDefinitionKind::Get | MethodDefinitionKind::Set => SymbolKind::Method,
        };
        let head = Span::new(method.decorators.last().map_or(method.span.start, |d| d.span.end), body.span.start);
        let signature = self.signature_text(head);
        self.member_block(method.span, node_kind, signature, parent);
    }

    /// A property holding an arrow or function expression: `handle = async (req) => { ... }`. Any other value is data,
    /// which the class block shows well enough.
    fn property_block(&mut self, property: &PropertyDefinition<'_>, parent: &ParentContext) {
        let Some(body_start) = property.value.as_ref().and_then(function_body_start) else { return };
        let head = Span::new(property.decorators.last().map_or(property.span.start, |d| d.span.end), body_start);
        let signature = self.signature_text(head);
        self.member_block(property.span, SymbolKind::Property, signature, parent);
    }

    /// An object property that is a method (`async f() { ... }`, a getter or a setter) or holds an arrow or function
    /// expression (`f: () => { ... }`). Any other value is data, which the object's block shows well enough.
    fn object_property_block(&mut self, property: &ObjectProperty<'_>, parent: &ParentContext) {
        let Some(body_start) = function_body_start(&property.value) else { return };
        let node_kind = if property.method || property.kind != PropertyKind::Init {
            SymbolKind::Method
        } else {
            SymbolKind::Property
        };
        let signature = self.signature_text(Span::new(property.span.start, body_start));
        self.member_block(property.span, node_kind, signature, parent);
    }

    fn member_block(&mut self, span: Span, node_kind: SymbolKind, signature: String, parent: &ParentContext) {
        let lines = self.lines.line(span.end) - self.lines.line(span.start) + 1;
        if lines >= MIN_MEMBER_LINES {
            self.push_block(span, node_kind, Some(signature), Some(parent.clone()));
        }
    }

    fn jsx(&mut self, program: &Program<'_>) {
        let mut collector = JsxCollector { lines: &self.lines, found: Vec::new() };
        collector.visit_program(program);
        self.out.jsx_elements = collector.found;
    }
}

/// The kind of block a top-level statement makes, or `None` when it is not one.
fn statement_kind(statement: &Statement<'_>) -> Option<SymbolKind> {
    match statement {
        Statement::FunctionDeclaration(_) => Some(SymbolKind::Function),
        Statement::ClassDeclaration(_) => Some(SymbolKind::Class),
        Statement::TSInterfaceDeclaration(_) => Some(SymbolKind::Interface),
        Statement::TSTypeAliasDeclaration(_) => Some(SymbolKind::TypeAlias),
        Statement::TSEnumDeclaration(_) => Some(SymbolKind::Enum),
        Statement::VariableDeclaration(_) => Some(SymbolKind::Variable),
        Statement::ExportDeclaration(export) => {
            Some(declaration_kind(&export.declaration).unwrap_or(SymbolKind::Other))
        }
        Statement::ExportDefaultDeclaration(export) => Some(match &export.declaration {
            ExportDefaultDeclarationKind::FunctionDeclaration(_) => SymbolKind::Function,
            ExportDefaultDeclarationKind::ClassDeclaration(_) => SymbolKind::Class,
            ExportDefaultDeclarationKind::TSInterfaceDeclaration(_) => SymbolKind::Interface,
            _ => SymbolKind::Other,
        }),
        Statement::ImportDeclaration(_)
        | Statement::ExportNamedDeclaration(_)
        | Statement::ExportFromDeclaration(_)
        | Statement::ExportAllDeclaration(_) => Some(SymbolKind::Other),
        _ => None,
